(function (global) {
  'use strict';
  var pack = {"manifest":{"id":"drilling-warning","sceneId":"d2","title":"井下复杂事故前兆预警","status":"ready","version":"1.0.0","updated":"2026-10-23","methods":["ts"],"tabs":{"background":{"label":"专业背景","lede":"在持续钻进工况下，井漏、气侵或卡钻可能伴随流量、立压与扭矩变化。把多通道变化相对正常基线统一到标准尺度，有助于从曲线中筛出需要人工复核的异常片段；异常本身不能确诊事故。","judge":[{"label":"数据来源","value":"教学合成","desc":"固定种子，可导出核查"},{"label":"方法类型","value":"多通道平滑异常监测","desc":"纯前端轻量计算"},{"label":"输出用途","value":"教学比较","desc":"不连接设备与现场系统"},{"label":"评价边界","value":"合成任务","desc":"不声称真实工程收益"}],"sections":[{"no":1,"en":"BUSINESS","title":"循环系统与异常线索","html":"<p>返出流量减去泵入流量得到净流量差；在排除加液、转罐等操作后，流量差积分与池量变化可共同提示流体收支异常。立管压力与扭矩用于补充另一类机械或循环异常线索。本例只模拟恒定钻进，不把三种合成模式视作可靠事故分类器。</p><figure class=\"figure\"><div style=\"overflow-x:auto\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 118\" role=\"img\" aria-label=\"循环系统与异常线索\" style=\"width:100%;min-width:560px;max-width:640px;display:block;margin:auto\"><rect x=\"18\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"105\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">循环与破岩</text><text x=\"105\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">流量差 · 立压 · 扭矩</text><path d=\"M194 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"208\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"295\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">工况内偏移</text><text x=\"295\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">相对正常基线比较</text><path d=\"M384 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"398\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"485\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">异常线索复核</text><text x=\"485\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">气侵 · 井漏 · 卡钻</text></svg></div><figcaption class=\"figcap\">业务关系示意，不是测量结果。窄屏可在图内横向滚动。</figcaption></figure>"},{"no":2,"en":"METHOD","title":"多通道平滑异常监测","html":"<p>正常段拟合每个通道的均值与标准差，后续数据只复用该基线。带符号标准分逐点进入 EWMA 指数加权平均，取绝对平滑值最大者作为异常分数；连续超限才报警。其价值是保留渐变趋势并抑制短暂噪声。实现是轻量统计时序监测，没有训练事故分类网络，分数不是事故概率。</p>"},{"no":3,"en":"DATA","title":"数据准备与评价切分","html":"<p>固定种子 20261024，每分钟采样，共 180 条。0–59 min 校准；60 min 后逐点监测。人为设定前兆 90–119 min、事件 120 min，正常场景不设事件。修改噪声、阈值和连续超限要求，可观察误报与漏报；观测时间控件只展示历史。现场应准备工况标签、传感器校准、转罐记录和专家复核事件时间。</p>"},{"no":4,"en":"LIMITS","title":"模型适用范围与工程约束","html":"<p>现场正常工况变化也会产生漂移；多通道独立标准化没有刻画协方差，EWMA 阈值由教学交互指定，不对应已标定误报概率。当前序列可反复调参，因此它是探索序列，不能称独立测试。报警应进入人工复核流程，本演示不输出井控处置。</p><p>专业资料与方法来源：</p><ul><li><a href=\"https://glossary.slb.com/terms/k/kick\" target=\"_blank\" rel=\"noopener noreferrer\">SLB：kick</a>：支持地层流体进入井眼的业务定义，不支持本例报警数值。</li><li><a href=\"https://www.itl.nist.gov/div898/handbook/pmc/section3/pmc324.htm\" target=\"_blank\" rel=\"noopener noreferrer\">NIST：EWMA Control Charts</a>：支持指数加权递推与渐变监测动机；本例使用最大通道分数和连续超限规则，未声称标准 EWMA 控制限保证。</li></ul>"}]},"workflow":{"label":"案例流程","title":"多通道平滑异常监测","lead":["在持续钻进工况下，井漏、气侵或卡钻可能伴随流量、立压与扭矩变化。把多通道变化相对正常基线统一到标准尺度，有助于从曲线中筛出需要人工复核的异常片段；异常本身不能确诊事故。"],"stats":[["数据","固定种子合成"],["运行方式","浏览器本地"],["工程用途","方法教学"]],"steps":[{"name":"工况与正常段选择","role":"数据","do":"固定合成恒定钻进段，分开校准与监测时间。","effect":"减少泵启停等工况切换混淆。","trap":"正常段污染会使后续偏移被低估。"},{"name":"通道基线标定","role":"算法","do":"仅用前 60 条求均值与标准差。","effect":"不同量纲的变化可比较。","trap":"禁止用事件后数据更新正常尺度。"},{"name":"因果时序评分","role":"算法","do":"递推 EWMA，取最大绝对偏移并统计连续超限。","effect":"保留缓慢漂移并标明贡献最大的通道。","trap":"分数不能当概率，噪声和采样间隔影响阈值。"},{"name":"预警复核与评价","role":"人工","do":"按已观测评价窗统计 TP、FP、FN、TN 与首次有效前兆报警。","effect":"把误报、漏报和提前量同时展示。","trap":"正常段误报不能计入有效提前量。"}],"metrics":{"title":"计算指标与评价边界","html":"<figure class=\"figure\"><div style=\"overflow-x:auto\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 118\" role=\"img\" aria-label=\"案例计算流程\" style=\"width:100%;min-width:560px;max-width:640px;display:block;margin:auto\"><rect x=\"18\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"105\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">正常段基线</text><text x=\"105\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">均值 / 标准差</text><path d=\"M194 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"208\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"295\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">EWMA 与持续超限</text><text x=\"295\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">当前及过去的观测</text><path d=\"M384 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"398\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"485\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">人工复核与评价</text><text x=\"485\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">误报 / 漏报 / 提前量</text></svg></div><figcaption class=\"figcap\">输入、计算与评价之间的关系示意；结果由演示实际计算。</figcaption></figure><p>样本级精确率=TP/(TP+FP)，召回率=TP/(TP+FN)；分母为零显示不可定义。只对 60–119 min 的已观测样本计数。事件前提前量=120−前兆窗内首次持续报警时间，未报警显示无有效前兆报警；正常场景不报告事故提前量。每分钟样本存在相关性，不能把样本召回率当独立事故检出率。</p>"},"fails":[{"name":"数据分布变化","why":"现场正常工况变化也会产生漂移；多通道独立标准化没有刻画协方差，EWMA 阈值由教学交互指定，不对应已标定误报概率。当前序列可反复调参，因此它是探索序列，不能称独立测试。报警应进入人工复核流程，本演示不输出井控处置。"},{"name":"合成结果误用","why":"所有数据、参数范围、阈值和响应系数均为教学合成设定；资料只支持业务定义和方法动机，不支持本例数值与现场收益。"}]},"demo":{"mode":"page","html":"demo/index.html","js":"demo/demo.js","label":"案例演示","height":1200,"intro":"在持续钻进工况下，井漏、气侵或卡钻可能伴随流量、立压与扭矩变化。把多通道变化相对正常基线统一到标准尺度，有助于从曲线中筛出需要人工复核的异常片段；异常本身不能确诊事故。"}}},"files":[{"name":"demo/demo.css","size":3674,"enc":"text","data":":root{font:16px/1.8 -apple-system,BlinkMacSystemFont,\"Segoe UI\",\"Microsoft YaHei\",sans-serif;color:#242b2e;background:#fbfaf6;--jade:#2f7d6b;--line:#ddd7c8;--muted:#56646b}\n*{box-sizing:border-box}body{margin:0}main{max-width:1200px;margin:auto;padding:24px}h1,h2,h3,p{margin:0}h1{font-size:clamp(24px,3vw,32px);line-height:1.4;margin:12px 0}h2{font-size:21px;line-height:1.5;margin-bottom:12px}h3{font-size:18px;margin:20px 0 10px}p{color:var(--muted)}header{margin-bottom:24px}header p{max-width:80ch}.badge{font-size:14px;color:#235f51;background:#e6f1ec;border-radius:4px;padding:5px 9px}.experiment{display:grid;grid-template-columns:285px minmax(0,1fr);border:1px solid var(--line);border-radius:12px;overflow:hidden;background:white}aside{background:#f3f5f0;padding:22px;border-right:1px solid var(--line)}.field{display:block;margin:18px 0}.field>span{display:flex;flex-wrap:wrap;justify-content:space-between;gap:6px;font-weight:600}.field output{color:var(--jade);font-variant-numeric:tabular-nums}input,select,button{font:inherit}input[type=range]{width:100%;accent-color:var(--jade);margin:14px 0;cursor:pointer}select{display:block;width:100%;min-height:44px;margin:8px 0;border:1px solid var(--line);border-radius:5px;background:white;padding:7px}small,.hint,.boundary{font-size:14px;color:var(--muted);line-height:1.75}.boundary{margin-top:18px;border-top:1px solid var(--line);padding-top:12px}button{min-height:44px;padding:8px 14px;color:white;background:var(--jade);border:1px solid var(--jade);border-radius:6px;cursor:pointer}button.quiet{background:white;color:var(--jade);border-color:var(--line)}button[hidden]{display:none}button:hover{filter:brightness(.95)}:focus-visible{outline:3px solid #41699b;outline-offset:3px}.results{padding:24px;min-width:0}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.metrics>div{padding:12px 14px;background:#f5f7f4;border:1px solid #e3e8e4;border-radius:6px}.metrics span{display:block;font-size:14px;color:var(--muted)}.metrics strong{display:block;font-size:23px;font-weight:600;line-height:1.5;color:#235f51;font-variant-numeric:tabular-nums}#status{padding:14px 0;font-size:15px}#apply{margin-bottom:16px}.chart{border-top:1px solid var(--line);padding-top:22px;margin-top:22px}.chart p{font-size:15px;line-height:1.8}.chart-scroll,.table-scroll{overflow:auto;overscroll-behavior-x:contain;padding-bottom:6px}svg{width:100%;max-width:700px;height:auto;display:block;margin:12px auto 4px}svg text{font:16px -apple-system,BlinkMacSystemFont,\"Microsoft YaHei\",sans-serif;fill:var(--muted)}.legend{display:flex;gap:10px 18px;flex-wrap:wrap;font-size:14px}.legend span{display:flex;align-items:center;gap:7px}.legend i{display:block;width:14px;height:4px}.details{margin-top:28px}.details>p{max-width:95ch}table{width:100%;border-collapse:collapse;font-size:15px;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:9px 12px;border-bottom:1px solid var(--line);white-space:nowrap}th{background:#f3f5f0;font-weight:600}#download{margin-top:18px}footer{font-size:14px;color:var(--muted);padding:18px 0;margin-top:26px;border-top:1px solid var(--line)}\n@media(max-width:1000px){.experiment{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line)}#controls{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}.field{margin:10px 0}}\n@media(max-width:600px){main{padding:12px}.results,aside{padding:16px}#controls{grid-template-columns:1fr}.metrics{gap:8px}.metrics strong{font-size:20px}.chart-scroll svg{width:640px;max-width:none}.badge{display:inline-block;font-size:13px}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n"},{"name":"demo/demo.js","size":4192,"enc":"text","data":"(function(){\n  'use strict';const M=WarningModel,F=CaseUI.f;\n  CaseUI.mount({id:'drilling-warning',title:'井下复杂事故前兆预警',intro:'在恒定钻进工况下，流量差、立管压力和扭矩相对正常段的偏移进入指数平滑监测。对比阈值与持续时间，观察漏报、误报和预警提前量。',boundary:'演示只筛查异常线索，不判定事故，不提供井控处置指令。接单根、泵启停和传感器故障需要另建工况基线。',\n    controls:[{id:'kind',label:'合成场景',value:'kick',options:[['kick','气侵线索'],['loss','井漏线索'],['stuck','卡钻线索'],['normal','正常波动']]},{id:'noise',label:'传感器噪声倍率',min:.5,max:3,step:.25,value:1},{id:'threshold',label:'异常分数阈值',min:.5,max:6,step:.1,value:2},{id:'persistence',label:'连续超限要求',min:1,max:8,step:1,value:3,unit:'min'},{id:'cursor',label:'已观测时间',min:60,max:179,step:1,value:119,unit:'min',hint:'只使用当前时刻及以前的样本；前兆标签仅用于事后评价。'}],\n    method:'种子 20261024，每分钟一条，共 180 条。0–59 min 正常段计算各通道均值和总体标准差；从 60 min 起计算带符号标准分的 EWMA，α=0.22，取三通道绝对平滑值的最大值。连续达到阈值后报警，不使用未来数据。教学前兆段 90–119 min，模拟事件时刻 120 min；混淆矩阵只统计 60–119 min 中已观测样本，事件后不计入。阈值由用户探索，当前序列不是独立测试集。',\n    compute:s=>{const raw=M.generate(s.kind,s.noise),model=M.calibrate(raw.slice(0,60)),rows=M.score(raw.slice(0,s.cursor+1),model,s.threshold,s.persistence),e=M.evaluate(rows),last=rows.at(-1),names=['流量差','立压','扭矩'],top=last.z.map((v,i)=>[Math.abs(v),i]).sort((a,b)=>b[0]-a[0])[0];\n      return {metrics:[['样本级精确率',e.precision===null?'不可定义':F(e.precision*100,1)+'%'],['前兆样本召回率',e.recall===null?'不可定义':F(e.recall*100,1)+'%'],['正常样本误报',e.fp+' 条'],['事件前提前量',e.lead===null?'尚无有效前兆报警':e.lead+' min']],summary:`当前分数 ${F(last.score)}，${last.alarm?'持续超限，建议人工复核':'未满足持续超限条件'}；最大贡献通道为${names[top[1]]}。正常场景没有正样本，召回率不可定义；无报警时精确率不可定义。`,\n        plots:[{title:'多通道标准化偏移',xLabel:'已观测时间 min',yLabel:'标准化 EWMA（无量纲）',xRange:[0,179],bands:s.kind==='normal'?[]:[{from:90,to:120}],vlines:s.kind==='normal'?[]:[120],note:'浅色区为教学前兆评价窗，虚线为合成事件时刻；正常场景无事件标记。三通道统一尺度便于比较，符号保留偏移方向。',series:names.map((name,k)=>({name,points:rows.filter(r=>r.t>=60).map(r=>[r.t,r.z[k]])}))},\n        {title:'异常分数与持续报警',xLabel:'已观测时间 min',yLabel:'异常分数（无量纲）',xRange:[0,179],yRange:[0,Math.max(8,...rows.map(r=>r.score))*1.1],hlines:[s.threshold],bands:s.kind==='normal'?[]:[{from:90,to:120}],note:'红虚线为用户阈值；蓝点表示已满足连续超限要求。分数不等于事故概率。',series:[{name:'最大通道分数',points:rows.map(r=>[r.t,r.score])},{name:'持续报警',dots:true,points:rows.filter(r=>r.alarm).map(r=>[r.t,r.score])}]},\n        {title:'返出流量差与累积池量',xLabel:'已观测时间 min',yLabel:'累计流量差 m³',xRange:[0,179],note:'每分钟净流量差乘 60/1000 积分得到池量变化，未模拟转罐与加液；原始各通道可导出核查。',series:[{name:'累计池量变化',points:rows.map(r=>[r.t,r.pit])}]}],\n        table:{title:'已观测评价窗混淆矩阵',headers:['教学标签','报警','未报警'],rows:[['前兆',e.tp,e.fn],['正常',e.fp,e.tn]],note:'精确率=TP/(TP+FP)，召回率=TP/(TP+FN)；提前量=120−前兆窗内首次有效报警时间。对正常段的误报不会算作提前预警。'},records:rows.map(r=>({minute:r.t,flow_difference_L_s:r.flow,standpipe_MPa:r.pressure,torque_kNm:r.torque,pit_change_m3:r.pit,score:r.score,alarm:r.alarm,precursor_label:r.precursor}))};}\n  });\n})();\n"},{"name":"demo/index.html","size":428,"enc":"text","data":"<!doctype html>\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>井下复杂事故前兆预警</title><link rel=\"stylesheet\" href=\"demo.css\"></head><body><main id=\"app\"></main><noscript>需要启用 JavaScript 才能运行本地计算。</noscript><script src=\"model.js\"></script><script src=\"ui.js\"></script><script src=\"demo.js\"></script></body></html>"},{"name":"demo/model.js","size":1886,"enc":"text","data":"(function(g){\n  'use strict';\n  function rng(seed){return function(){seed=(1664525*seed+1013904223)>>>0;return seed/4294967296;};}\n  function generate(kind,noise){\n    const rand=rng(20261024);let pit=0;\n    return Array.from({length:180},(_,t)=>{\n      const a=t<90?0:Math.min(1,(t-90)/30), active=kind!=='normal';\n      const flow=(rand()-.5)*noise*1.5+(active&&kind==='kick'?3*a:active&&kind==='loss'?-3*a:0);\n      const pressure=18+(rand()-.5)*noise*.6+(kind==='stuck'?3*a:kind==='loss'?-1.5*a:0);\n      const torque=12+(rand()-.5)*noise*1.2+(kind==='stuck'?6*a:0);\n      pit+=flow*60/1000;\n      return {t,flow,pressure,torque,pit,precursor:active&&t>=90&&t<120};\n    });\n  }\n  function calibrate(rows){return ['flow','pressure','torque'].map(key=>{\n    const mean=rows.reduce((s,r)=>s+r[key],0)/rows.length;\n    return {key,mean,sd:Math.sqrt(rows.reduce((s,r)=>s+(r[key]-mean)**2,0)/rows.length)||1};\n  });}\n  function score(rows,model,threshold,persistence){\n    let ew=[0,0,0],run=0;\n    return rows.map((r,i)=>{\n      if(i<60)return {...r,score:0,alarm:false,z:[0,0,0]};\n      const z=model.map(m=>(r[m.key]-m.mean)/m.sd);\n      ew=ew.map((v,k)=>.22*z[k]+.78*v);\n      const value=Math.max(...ew.map(Math.abs));run=value>=threshold?run+1:0;\n      return {...r,score:value,alarm:run>=persistence,z:ew.slice()};\n    });\n  }\n  function evaluate(rows){\n    let tp=0,fp=0,tn=0,fn=0;\n    rows.filter(r=>r.t>=60&&r.t<120).forEach(r=>{if(r.precursor){if(r.alarm)tp++;else fn++;}else{if(r.alarm)fp++;else tn++;}});\n    const first=rows.find(r=>r.t>=90&&r.t<120&&r.precursor&&r.alarm);\n    return {tp,fp,tn,fn,precision:tp+fp?tp/(tp+fp):null,recall:tp+fn?tp/(tp+fn):null,lead:first?120-first.t:null};\n  }\n  const api={rng,generate,calibrate,score,evaluate};\n  if(typeof module!=='undefined')module.exports=api;else g.WarningModel=api;\n})(typeof window!=='undefined'?window:globalThis);\n"},{"name":"demo/ui.js","size":6241,"enc":"text","data":"(function(g){\n  'use strict';\n  const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n  const f=(v,n=2)=>v===null||!Number.isFinite(v)?'不可定义':v.toFixed(n);\n  function plot(p,index){\n    const W=700,H=340,L=85,R=24,T=38,B=64;\n    const all=p.series.flatMap(s=>s.points).filter(a=>a.every(Number.isFinite));\n    const extent=(k)=>{const v=all.map(a=>a[k]);let a=Math.min(...v),b=Math.max(...v);if(a===b){a-=1;b+=1;}return [a,b];};\n    const xr=p.xRange||extent(0),yr=p.yRange||extent(1),x=v=>L+(v-xr[0])/(xr[1]-xr[0])*(W-L-R),y=v=>H-B-(v-yr[0])/(yr[1]-yr[0])*(H-T-B);\n    let svg=`<defs><clipPath id=\"clip${index}\"><rect x=\"${L}\" y=\"${T}\" width=\"${W-L-R}\" height=\"${H-T-B}\"/></clipPath></defs>`;\n    for(let i=0;i<=4;i++){const xv=xr[0]+(xr[1]-xr[0])*i/4,yv=yr[0]+(yr[1]-yr[0])*i/4;svg+=`<path d=\"M${L} ${y(yv)}H${W-R}\" stroke=\"#e3e8e4\"/><text x=\"${L-10}\" y=\"${y(yv)+5}\" text-anchor=\"end\">${f(yv,p.decimals??1)}</text><text x=\"${x(xv)}\" y=\"${H-B+27}\" text-anchor=\"middle\">${f(xv,p.xDecimals??0)}</text>`;}\n    svg+=`<text x=\"${L}\" y=\"22\">${esc(p.yLabel)}</text><text x=\"${(L+W-R)/2}\" y=\"${H-8}\" text-anchor=\"middle\">${esc(p.xLabel)}</text><g clip-path=\"url(#clip${index})\">`;\n    (p.bands||[]).forEach(b=>{svg+=`<rect x=\"${x(b.from)}\" y=\"${T}\" width=\"${x(b.to)-x(b.from)}\" height=\"${H-T-B}\" fill=\"#f8ecdf\"/>`;});\n    (p.hlines||[]).forEach(v=>svg+=`<path d=\"M${L} ${y(v)}H${W-R}\" stroke=\"#a34138\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>`);\n    (p.vlines||[]).forEach(v=>svg+=`<path d=\"M${x(v)} ${T}V${H-B}\" stroke=\"#8e5229\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>`);\n    const colors=['#2f7d6b','#41699b','#b26a39','#7e5a8d'];\n    p.series.forEach((s,i)=>{const pts=s.points.filter(a=>a.every(Number.isFinite)),color=s.color||colors[i%4];if(s.dots)pts.forEach(a=>svg+=`<circle cx=\"${x(a[0])}\" cy=\"${y(a[1])}\" r=\"3.5\" fill=\"${color}\" opacity=\".65\"><title>${esc(s.name)}：${f(a[0])}, ${f(a[1])}</title></circle>`);else svg+=`<path d=\"${pts.map((a,j)=>(j?'L':'M')+x(a[0])+','+y(a[1])).join(' ')}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2.5\" ${s.dashed?'stroke-dasharray=\"7 5\"':''}/>`;});svg+='</g>';\n    return `<article class=\"chart\"><h2>${esc(p.title)}</h2><p>${esc(p.note)}</p><div class=\"chart-scroll\" role=\"region\" tabindex=\"0\" aria-label=\"${esc(p.title)}，窄屏可横向滚动\"><svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"${esc(p.title+'；'+p.yLabel+'；'+p.xLabel)}\">${svg}</svg></div><div class=\"legend\">${p.series.map((s,i)=>`<span><i style=\"background:${s.color||colors[i%4]}\"></i>${esc(s.name)}</span>`).join('')}</div></article>`;\n  }\n  function mount(c){\n    const root=document.getElementById('app');let result;\n    root.innerHTML=`<header><span class=\"badge\">教学合成数据 · 本地计算 · 固定种子</span><h1>${esc(c.title)}</h1><p>${esc(c.intro)}</p></header><section class=\"experiment\"><aside><h2>实验设置</h2><form id=\"controls\">${c.controls.map(a=>`<label class=\"field\" for=\"${a.id}\"><span>${esc(a.label)} <output id=\"${a.id}-value\"></output></span>${a.options?`<select id=\"${a.id}\">${a.options.map(o=>`<option value=\"${esc(o[0])}\">${esc(o[1])}</option>`).join('')}</select>`:`<input id=\"${a.id}\" type=\"range\" min=\"${a.min}\" max=\"${a.max}\" step=\"${a.step}\" value=\"${a.value}\">`}<small>${esc(a.hint||'')}</small></label>`).join('')}</form><button id=\"reset\" class=\"quiet\" type=\"button\">恢复初始设置</button><p class=\"boundary\">${esc(c.boundary)}</p></aside><div class=\"results\"><h2>计算结果</h2><div id=\"metrics\" class=\"metrics\"></div><p id=\"status\" role=\"status\"></p><button id=\"apply\" type=\"button\" hidden>应用推荐参数</button><div id=\"plots\"></div></div></section><section class=\"details\"><h2>方法与评价边界</h2><p>${esc(c.method)}</p><div id=\"table\"></div><button id=\"download\" class=\"quiet\" type=\"button\">导出当前实验 CSV</button></section><footer>所有范围、阈值、响应系数和目标均为教学设置；合成评价不能证明现场效果。演示不连接设备。图表可通过下方数据表及 CSV 核对。</footer>`;\n    const read=()=>Object.fromEntries(c.controls.map(a=>[a.id,a.options?document.getElementById(a.id).value:+document.getElementById(a.id).value]));\n    function render(){const s=read();c.controls.forEach(a=>document.getElementById(a.id+'-value').textContent=a.options?'':s[a.id]+(a.unit?' '+a.unit:''));result=c.compute(s);document.getElementById('metrics').innerHTML=result.metrics.map(a=>`<div><span>${esc(a[0])}</span><strong>${esc(a[1])}</strong></div>`).join('');document.getElementById('status').textContent=result.summary;document.getElementById('plots').innerHTML=result.plots.map(plot).join('');const table=result.table;document.getElementById('table').innerHTML=`<h3>${esc(table.title)}</h3><div class=\"table-scroll\"><table><thead><tr>${table.headers.map(v=>`<th scope=\"col\">${esc(v)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class=\"hint\">${esc(table.note||'')}</p>`;document.getElementById('apply').hidden=!result.apply;}\n    document.getElementById('controls').addEventListener('submit',e=>e.preventDefault());\n    c.controls.forEach(a=>document.getElementById(a.id).addEventListener(a.options?'change':'input',render));\n    document.getElementById('reset').onclick=()=>{c.controls.forEach(a=>document.getElementById(a.id).value=a.value);render();};\n    document.getElementById('apply').onclick=()=>{if(result.apply){Object.entries(result.apply).forEach(([k,v])=>document.getElementById(k).value=v);render();}};\n    document.getElementById('download').onclick=()=>{const rows=result.records;if(!rows.length)return;const keys=Object.keys(rows[0]),cell=v=>'\"'+String(v??'').replace(/\"/g,'\"\"')+'\"';const csv='\\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\\r\\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=c.id+'-synthetic.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};\n    c.controls.forEach(a=>document.getElementById(a.id).value=a.value);render();\n  }\n  g.CaseUI={mount,f,plot};\n})(window);\n"}]};
  // Local uploads take precedence. Keep the original importer and its package contract.
  var sc = global.ATLAS.index.byScene[pack.manifest.sceneId];
  var existing = global.Cases.get(pack.manifest.id);
  if (existing) {
    if (sc && existing.tabs && existing.tabs.demo) sc.demo = true;
    return;
  }
  if (global.CaseImport.blockedList().indexOf(pack.manifest.id) >= 0) return;
  var c = pack.manifest;
  var cfg = c.tabs.demo;
  var handle = null;
  c.status = 'ready';
  c.tabs.demo = {
    label: cfg.label, intro: cfg.intro,
    mount: function (root, ctx) {
      handle = global.CaseDemoHost.create(root, { files: pack.files, demo: cfg, meta: c }, ctx);
    },
    unmount: function () { if (handle) { handle.destroy(); handle = null; } }
  };
  global.Cases.register(c);
  if (sc) sc.demo = true;
})(window);
